class FieldSimulator:
    def __init__(self, gravity=-9.81):
        self.gravity = gravity
        self.height = 0.0
        self.velocity = 0.0
        self.field_intensity = 0.0
        self.field_radius = 0.0

    def apply_antigravity_field(self, radius, power):
        """Applies an upward anti-gravitational field vector."""
        self.field_radius = radius
        self.field_intensity = power

    def step(self):
        # Calculate local field force based on distance
        # As height increases, field attenuation follows inverse square law
        distance = max(1.0, self.height)
        field_force = (self.field_intensity * 15.0) / (distance ** 1.5)

        effective_accel = self.gravity + field_force
        self.velocity += effective_accel * 0.1  # dt = 0.1s
        self.height += self.velocity * 0.1

        if self.height < 0.0:
            self.height = 0.0
            self.velocity = 0.0`
