export function renderContributionGraph(state, actions) {
  const contributions = state.user.contributions || {};

  // Calculate total contributions in the last year
  let totalCommits = 0;
  Object.values(contributions).forEach(day => {
    totalCommits += day.count;
  });

  // Calculate day elements
  const today = new Date();
  const oneYearAgo = new Date();
  oneYearAgo.setDate(today.getDate() - 364); // 52 weeks * 7 days = 364 days

  // Align to the start of the week (Sunday)
  const startDay = oneYearAgo.getDay();
  const paddingDays = startDay; // Days of padding at the start

  let graphHtml = '';

  // We need 365 + padding elements to fill the grid
  // Standard grid flow is top-to-bottom, left-to-right (column by column)
  // CSS Grid auto-flow column solves this natively!

  // Empty slots for padding
  for (let i = 0; i < paddingDays; i++) {
    graphHtml += `<div class="contrib-day-empty" style="width: 11px; height: 11px; visibility: hidden;"></div>`;
  }

  // Actual contribution days
  let current = new Date(oneYearAgo);
  while (current <= today) {
    const dateStr = current.toISOString().split('T')[0];
    const data = contributions[dateStr] || { count: 0, level: 0 };
    const formattedDate = current.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

    graphHtml += `
      <div 
        class="contrib-day" 
        data-level="${data.level}" 
        data-count="${data.count}" 
        data-date="${formattedDate}" 
        style="grid-row: ${(current.getDay() + 1)};"
      ></div>
    `;
    current.setDate(current.getDate() + 1);
  }

  return `
    <div class="contrib-graph-card">
      <div class="contrib-header">
        <span class="contrib-title">${totalCommits} contributions in the last year</span>
        <span style="font-size: 0.75rem; color: var(--text-secondary);">Activity Density</span>
      </div>

      <div class="contrib-grid-wrapper">
        <div class="contrib-grid" style="display: grid; grid-auto-flow: column; grid-template-rows: repeat(7, 11px); grid-template-columns: repeat(53, 11px); gap: 3px;">
          ${graphHtml}
        </div>
      </div>

      <div class="contrib-legend">
        <span>Less</span>
        <div class="contrib-legend-box" data-level="0" style="background-color: #161b22;"></div>
        <div class="contrib-legend-box" data-level="1" style="background-color: #0e4429;"></div>
        <div class="contrib-legend-box" data-level="2" style="background-color: #006d32;"></div>
        <div class="contrib-legend-box" data-level="3" style="background-color: #26a641;"></div>
        <div class="contrib-legend-box" data-level="4" style="background-color: #39d353;"></div>
        <span>More</span>
      </div>

      <!-- Shared Tooltip -->
      <div id="contrib-tooltip" class="contrib-tooltip"></div>
    </div>
  `;
}

export function attachContributionGraphListeners(state, actions) {
  const days = document.querySelectorAll(".contrib-day");
  const tooltip = document.getElementById("contrib-tooltip");

  if (!tooltip) return;

  days.forEach(day => {
    day.addEventListener("mouseenter", (e) => {
      const count = day.getAttribute("data-count");
      const date = day.getAttribute("data-date");
      const text = `${count === "0" ? "No" : count} contribution${count === "1" ? "" : "s"} on ${date}`;

      tooltip.innerText = text;
      tooltip.style.display = "block";

      const rect = day.getBoundingClientRect();
      const scrollLeft = window.pageXOffset || document.documentElement.scrollLeft;
      const scrollTop = window.pageYOffset || document.documentElement.scrollTop;

      tooltip.style.left = `${rect.left + scrollLeft - tooltip.offsetWidth / 2 + 5}px`;
      tooltip.style.top = `${rect.top + scrollTop - tooltip.offsetHeight - 8}px`;
    });

    day.addEventListener("mouseleave", () => {
      tooltip.style.display = "none";
    });
  });
}

