export function renderRepoList(state, actions) {
  // Filter and sort logic
  let filtered = [...state.repos];

  // 1. Query search filter
  if (state.searchQuery) {
    const q = state.searchQuery.toLowerCase();
    filtered = filtered.filter(repo => 
      repo.name.toLowerCase().includes(q) || 
      (repo.description && repo.description.toLowerCase().includes(q))
    );
  }

  // 2. Language filter
  if (state.filterLanguage && state.filterLanguage !== "All") {
    filtered = filtered.filter(repo => repo.language === state.filterLanguage);
  }

  // 3. Type filter
  if (state.filterType && state.filterType !== "All") {
    const showPrivate = state.filterType === "Private";
    filtered = filtered.filter(repo => repo.isPrivate === showPrivate);
  }

  // Get distinct languages in state for filter dropdown
  const allLanguages = ["All", ...new Set(state.repos.map(r => r.language).filter(Boolean))];

  // Render cards
  const cardsHtml = filtered.map(repo => {
    const updatedDate = new Date(repo.updatedAt).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric'
    });

    const langLower = (repo.language || '').toLowerCase();

    return `
      <div class="repo-card" data-id="${repo.id}">
        <div class="repo-card-top">
          <div class="repo-card-title-area">
            <span class="repo-card-title">${repo.name}</span>
            <span class="badge">${repo.isPrivate ? 'Private' : 'Public'}</span>
          </div>
          <button class="btn btn-sm star-btn" data-id="${repo.id}">
            <i data-lucide="star" style="width: 14px; height: 14px;"></i>
            <span>Star</span>
          </button>
        </div>

        <p class="repo-card-desc">${repo.description || 'No description provided.'}</p>

        <div class="repo-card-meta">
          ${repo.language ? `
            <div class="lang-indicator">
              <span class="lang-dot lang-${langLower}"></span>
              <span>${repo.language}</span>
            </div>
          ` : ''}

          <div class="repo-meta-item">
            <i data-lucide="star" style="width: 14px; height: 14px; color: var(--text-muted);"></i>
            <span>${repo.stars}</span>
          </div>

          <div class="repo-meta-item">
            <i data-lucide="git-fork" style="width: 14px; height: 14px; color: var(--text-muted);"></i>
            <span>${repo.forks}</span>
          </div>

          <div style="font-size: 0.75rem; color: var(--text-muted);">
            Updated on ${updatedDate}
          </div>
        </div>
      </div>
    `;
  }).join('');

  return `
    <div class="content-section">
      <!-- Repo Filters -->
      <div class="repo-filters">
        <div class="filter-search search-container">
          <i data-lucide="search"></i>
          <input 
            type="text" 
            class="search-input" 
            placeholder="Find a repository..." 
            id="repo-search-input"
            value="${state.searchQuery || ''}"
          />
        </div>

        <select class="select-filter" id="repo-type-select">
          <option value="All" ${state.filterType === "All" ? "selected" : ""}>Type: All</option>
          <option value="Public" ${state.filterType === "Public" ? "selected" : ""}>Type: Public</option>
          <option value="Private" ${state.filterType === "Private" ? "selected" : ""}>Type: Private</option>
        </select>

        <select class="select-filter" id="repo-lang-select">
          ${allLanguages.map(lang => `
            <option value="${lang}" ${state.filterLanguage === lang ? "selected" : ""}>Language: ${lang}</option>
          `).join('')}
        </select>

        <button class="btn btn-primary" id="repo-list-new-btn">
          <i data-lucide="book-open"></i>
          <span>New Repository</span>
        </button>
      </div>

      <!-- Repo Cards List -->
      <div class="repo-card-grid">
        ${cardsHtml || `
          <div class="empty-view-placeholder">
            <i data-lucide="search-code"></i>
            <h3>No repositories match your filters</h3>
            <p>Try clearing some search queries or filters to find what you need.</p>
          </div>
        `}
      </div>
    </div>
  `;
}

export function attachRepoListListeners(state, actions) {
  // Card click navigations
  const cards = document.querySelectorAll(".repo-card");
  cards.forEach(card => {
    card.addEventListener("click", (e) => {
      // If clicking inside a button, ignore
      if (e.target.closest("button") || e.target.closest("a")) return;
      const repoId = card.getAttribute("data-id");
      actions.navigateToRepo(repoId);
    });
  });

  // Star buttons
  const starBtns = document.querySelectorAll(".star-btn");
  starBtns.forEach(btn => {
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      const repoId = btn.getAttribute("data-id");
      actions.starRepository(repoId);
    });
  });

  // Search input
  const searchInput = document.getElementById("repo-search-input");
  if (searchInput) {
    searchInput.addEventListener("input", (e) => {
      actions.setSearchQuery(e.target.value);
    });
    searchInput.addEventListener("focus", () => {
      const val = searchInput.value;
      searchInput.value = '';
      searchInput.value = val;
    });
  }

  // Type dropdown
  const typeSelect = document.getElementById("repo-type-select");
  if (typeSelect) {
    typeSelect.addEventListener("change", (e) => {
      actions.setFilterType(e.target.value);
    });
  }

  // Language dropdown
  const langSelect = document.getElementById("repo-lang-select");
  if (langSelect) {
    langSelect.addEventListener("change", (e) => {
      actions.setFilterLanguage(e.target.value);
    });
  }

  // New repo button
  const newBtn = document.getElementById("repo-list-new-btn");
  if (newBtn) {
    newBtn.addEventListener("click", () => {
      actions.toggleCreateRepoModal(true);
    });
  }
}

