export function renderRepoHeader(state, actions) {
  const repo = state.repos.find(r => r.id === state.activeRepoId);
  if (!repo) return '';

  const openIssuesCount = repo.issues.filter(i => i.status === "open").length;
  const openPrsCount = repo.pullRequests.filter(p => p.status === "open").length;

  const tabs = [
    { id: 'code', label: 'Code', icon: 'code' },
    { id: 'commits', label: 'Commits', icon: 'history', count: repo.commits.length },
    { id: 'issues', label: 'Issues', icon: 'circle-dot', count: openIssuesCount },
    { id: 'pulls', label: 'Pull Requests', icon: 'git-pull-request', count: openPrsCount },
    { id: 'settings', label: 'Settings', icon: 'settings' }
  ];

  const tabHtml = tabs.map(tab => {
    const isActive = state.activeRepoTab === tab.id;
    const hasCount = tab.count !== undefined;

    return `
      <div class="repo-tab ${isActive ? 'active' : ''}" data-tab="${tab.id}">
        <i data-lucide="${tab.icon}" style="width: 16px; height: 16px;"></i>
        <span>${tab.label}</span>
        ${hasCount ? `<span class="repo-tab-count">${tab.count}</span>` : ''}
      </div>
    `;
  }).join('');

  return `
    <div class="repo-detail-header">
      <div class="repo-detail-title-line">
        <div class="repo-detail-path">
          <i data-lucide="${repo.isPrivate ? 'lock' : 'book-marked'}" style="color: var(--text-secondary); width: 20px; height: 20px;"></i>
          <span class="owner">${state.user.username}</span>
          <span class="separator">/</span>
          <span class="name" id="repo-header-name">${repo.name}</span>
          <span class="badge" style="margin-left: 0.5rem;">${repo.isPrivate ? 'Private' : 'Public'}</span>
        </div>

        <div class="repo-detail-actions">
          <button class="btn btn-sm" id="repo-header-watch-btn">
            <i data-lucide="eye" style="width: 14px; height: 14px;"></i>
            <span>Watch</span>
          </button>

          <button class="btn btn-sm" id="repo-header-fork-btn">
            <i data-lucide="git-fork" style="width: 14px; height: 14px;"></i>
            <span>Fork</span>
            <span class="repo-tab-count" style="background-color: var(--bg-primary);">${repo.forks}</span>
          </button>

          <button class="btn btn-sm star-btn" data-id="${repo.id}">
            <i data-lucide="star" style="width: 14px; height: 14px;"></i>
            <span>Star</span>
            <span class="repo-tab-count" style="background-color: var(--bg-primary);">${repo.stars}</span>
          </button>
        </div>
      </div>

      <div class="repo-tabs">
        ${tabHtml}
      </div>
    </div>
  `;
}

