export function renderFileExplorer(state, actions) {
  const repo = state.repos.find(r => r.id === state.activeRepoId);
  if (!repo) return '';

  const activeFilePath = state.activeFilePath || (repo.files[0] ? repo.files[0].path : null);
  const activeFile = repo.files.find(f => f.path === activeFilePath);

  // Build the hierarchical tree from the flat files list
  const tree = buildFileTree(repo.files);

  // Render tree node HTML recursively
  function renderNode(node, depth = 0) {
    if (node.type === 'file') {
      const isActive = node.path === activeFilePath;
      return `
        <li class="tree-item-container">
          <div class="tree-node ${isActive ? 'active' : ''}" data-type="file" data-path="${node.path}">
            <div class="tree-node-icon file ${isActive ? 'active' : ''}">
              <i data-lucide="file-code"></i>
            </div>
            <span>${node.name}</span>
          </div>
        </li>
      `;
    } else {
      // Folder
      const isExpanded = state.expandedFolders ? state.expandedFolders.includes(node.path) : true; // default expanded
      const childrenHtml = isExpanded 
        ? `<ul class="tree-sub-list">${Object.values(node.children).map(child => renderNode(child, depth + 1)).join('')}</ul>`
        : '';

      return `
        <li class="tree-item-container">
          <div class="tree-node folder-node" data-type="folder" data-path="${node.path}">
            <div class="tree-node-icon folder">
              <i data-lucide="${isExpanded ? 'folder-open' : 'folder'}"></i>
            </div>
            <span style="font-weight: 600; color: var(--text-primary);">${node.name}</span>
          </div>
          ${childrenHtml}
        </li>
      `;
    }
  }

  const treeHtml = Object.values(tree.children)
    .map(child => renderNode(child, 0))
    .join('');

  // Right pane: Code viewer or editor
  let codePaneHtml = '';
  if (activeFile) {
    const isEditing = state.isEditingFile === activeFilePath;
    const lines = activeFile.content.split('\n');
    const lineNumbersHtml = lines.map((_, i) => i + 1).join('\n');

    // Simple syntax highlighting helper
    const highlightedCode = highlightCode(activeFile.content, getFileExtension(activeFile.path));

    codePaneHtml = `
      <div class="file-view-pane">
        <div class="file-view-header">
          <div class="file-view-title">
            <i data-lucide="file-text"></i>
            <span>${activeFile.path}</span>
            <span style="font-size: 0.75rem; color: var(--text-muted); margin-left: 0.5rem;">(${lines.length} lines)</span>
          </div>

          <div class="file-view-actions">
            ${isEditing ? `
              <button class="btn btn-sm btn-primary" id="commit-changes-trigger-btn">Commit Changes</button>
              <button class="btn btn-sm" id="cancel-edit-btn">Cancel</button>
            ` : `
              <button class="btn btn-sm" id="edit-file-btn">
                <i data-lucide="edit-3" style="width: 14px; height: 14px;"></i>
                <span>Edit</span>
              </button>
            `}
          </div>
        </div>

        <div class="file-content-container">
          ${isEditing ? `
            <div style="display: flex; flex-direction: column; height: 100%;">
              <textarea class="composer-textarea" id="file-editor-textarea" style="flex-grow: 1; font-family: var(--font-mono); font-size: 0.85rem; padding: 1rem; border: none; background: #07090e; height: 400px;">${activeFile.content}</textarea>

              <!-- Commit form section -->
              <div style="padding: 1.25rem; border-top: 1px solid var(--border-color); background-color: var(--bg-tertiary);">
                <h4 style="font-size: 0.85rem; font-weight: 700; margin-bottom: 0.75rem;">Commit changes</h4>
                <div class="form-group" style="margin-bottom: 0.75rem;">
                  <input type="text" class="form-input" id="commit-msg-input" placeholder="Update ${activeFile.path.split('/').pop()}" />
                </div>
                <div class="form-group">
                  <textarea class="form-input" id="commit-desc-input" placeholder="Add an optional extended description..." rows="2" style="resize: vertical;"></textarea>
                </div>
              </div>
            </div>
          ` : `
            <div class="code-editor-area">
              <pre class="line-numbers">${lineNumbersHtml}</pre>
              <pre class="code-lines"><code>${highlightedCode}</code></pre>
            </div>
          `}
        </div>
      </div>
    `;
  } else {
    codePaneHtml = `
      <div class="empty-view-placeholder">
        <i data-lucide="folder-git"></i>
        <h3>Repository is empty</h3>
        <p>Create a README.md file to get started.</p>
      </div>
    `;
  }

  return `
    <div class="code-layout">
      <!-- File Tree Pane -->
      <div class="file-tree-pane">
        <div class="file-tree-header">Files</div>
        <ul class="tree-list">
          ${treeHtml}
        </ul>
      </div>

      <!-- Code View Pane -->
      <div class="file-view-pane-wrapper" style="display: flex; flex-direction: column; overflow: hidden;">
        ${codePaneHtml}
      </div>
    </div>
  `;
}

// Utility to build file tree object
function buildFileTree(files) {
  const root = { name: 'root', type: 'folder', children: {} };

  files.forEach(file => {
    const parts = file.path.split('/');
    let current = root;

    for (let i = 0; i < parts.length; i++) {
      const part = parts[i];
      const isLast = i === parts.length - 1;

      if (isLast) {
        current.children[part] = {
          name: part,
          type: 'file',
          path: file.path
        };
      } else {
        if (!current.children[part]) {
          current.children[part] = {
            name: part,
            type: 'folder',
            path: parts.slice(0, i + 1).join('/'),
            children: {}
          };
        }
        current = current.children[part];
      }
    }
  });

  return root;
}

function getFileExtension(path) {
  return path.split('.').pop().toLowerCase();
}

// Quick Regex Syntax Highlighting
function highlightCode(code, ext) {
  // Escape HTML tags to prevent security issues or broken layouts
  let escaped = code
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");

  if (ext === 'py') {
    // Keywords
    escaped = escaped.replace(/\b(def|class|import|from|return|if|elif|else|for|while|in|as|print|is|not|and|or|None|self)\b/g, '<span class="code-keyword">$1</span>');
    // Comments
    escaped = escaped.replace(/(#.*)/g, '<span class="code-comment">$1</span>');
    // Strings
    escaped = escaped.replace(/(&quot;.*?&quot;|&#039;.*?&#039;)/g, '<span class="code-string">$1</span>');
    // Numbers
    escaped = escaped.replace(/\b(\d+)\b/g, '<span class="code-number">$1</span>');
  } else if (ext === 'js' || ext === 'jsx') {
    // Keywords
    escaped = escaped.replace(/\b(const|let|var|function|return|if|else|for|while|switch|case|break|export|import|from|default|class|extends|new|true|false)\b/g, '<span class="code-keyword">$1</span>');
    // Strings
    escaped = escaped.replace(/(&quot;.*?&quot;|&#039;.*?&#039;|`.*?`)/g, '<span class="code-string">$1</span>');
    // Comments
    escaped = escaped.replace(/(\/\/.*|\/\*[\s\S]*?\*\/)/g, '<span class="code-comment">$1</span>');
    // Numbers
    escaped = escaped.replace(/\b(\d+)\b/g, '<span class="code-number">$1</span>');
  } else if (ext === 'css') {
    // Attributes
    escaped = escaped.replace(/\b([a-zA-Z\-]+)(?=\s*:)/g, '<span class="code-attr">$1</span>');
    // Comments
    escaped = escaped.replace(/(\/\*[\s\S]*?\*\/)/g, '<span class="code-comment">$1</span>');
    // Numbers/Units
    escaped = escaped.replace(/\b(\d+px|\d+rem|\d+s|\d+%|\b\d+\b)/g, '<span class="code-number">$1</span>');
  } else if (ext === 'html') {
    // Tags
    escaped = escaped.replace(/(&lt;\/?[a-zA-Z0-9]+)(&gt;|\s)/g, '<span class="code-tag">$1</span>$2');
    // Comments
    escaped = escaped.replace(/(&lt;!--[\s\S]*?--&gt;)/g, '<span class="code-comment">$1</span>');
  }

  return escaped;
}

export function attachFileExplorerListeners(state, actions) {
  // Tree Nodes click (files or folder toggles)
  const treeNodes = document.querySelectorAll(".tree-node");
  treeNodes.forEach(node => {
    node.addEventListener("click", () => {
      const type = node.getAttribute("data-type");
      const path = node.getAttribute("data-path");

      if (type === "file") {
        actions.selectFile(path);
      } else {
        // Toggle folder expansion
        actions.toggleFolder(path);
      }
    });
  });

  // Edit file button
  const editBtn = document.getElementById("edit-file-btn");
  if (editBtn) {
    editBtn.addEventListener("click", () => {
      const repo = state.repos.find(r => r.id === state.activeRepoId);
      const path = state.activeFilePath || (repo.files[0] ? repo.files[0].path : null);
      actions.setEditingFile(path);
    });
  }

  // Cancel edit button
  const cancelBtn = document.getElementById("cancel-edit-btn");
  if (cancelBtn) {
    cancelBtn.addEventListener("click", () => {
      actions.setEditingFile(null);
    });
  }

  // Commit changes button
  const commitBtn = document.getElementById("commit-changes-trigger-btn");
  if (commitBtn) {
    commitBtn.addEventListener("click", () => {
      const repo = state.repos.find(r => r.id === state.activeRepoId);
      const path = state.activeFilePath || (repo.files[0] ? repo.files[0].path : null);
      const textarea = document.getElementById("file-editor-textarea");
      const msgInput = document.getElementById("commit-msg-input");

      const newContent = textarea ? textarea.value : '';
      const commitMsg = (msgInput && msgInput.value) ? msgInput.value : `Update ${path.split('/').pop()}`;

      actions.commitFileChanges(repo.id, path, newContent, commitMsg);
    });
  }
}

