export function renderIssueTracker(state, actions) {
  const repo = state.repos.find(r => r.id === state.activeRepoId);
  if (!repo) return '';

  // 1. Thread detail view (if selected)
  if (state.selectedIssueId) {
    const issue = repo.issues.find(i => i.id === Number(state.selectedIssueId));
