    const commentsHtml = [
      // Main issue description as first bubble
      {
        author: issue.author,
        isOwner: issue.author === state.user.username,
        createdAt: issue.createdAt,
        body: issue.description
      },
      ...issue.comments
    ].map((c, index) => {
      const formattedDate = new Date(c.createdAt).toLocaleDateString('en-US', {
        month: 'short',
        day: 'numeric',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      });
      const isUser = c.author === state.user.username;

      return `
        <div class="comment-item">
          <div class="comment-avatar-col">
            <img src="${isUser ? state.user.avatarUrl : 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=60&auto=format&fit=crop&q=80'}" alt="${c.author}" class="avatar" />
          </div>

          <div class="comment-bubble">
