      `;
    }).join('');

    return `
      <div class="issue-detail-container">
        <!-- Back navigation -->
        <button class="btn btn-sm" id="issue-back-btn">
          <i data-lucide="arrow-left" style="width: 14px; height: 14px;"></i>
          <span>Back to Issues</span>
        </button>

        <!-- Header status details -->
        <div class="issue-detail-title-block">
          <div class="issue-detail-title-row">
            <h2 class="issue-detail-title-text">
              <span>${issue.title}</span>
              <span class="issue-detail-number">#${issue.id}</span>
            </h2>

            <div class="repo-detail-actions">
              <button class="btn btn-sm btn-danger" id="toggle-issue-state-btn">
                <i data-lucide="${issue.status === 'open' ? 'circle-slash' : 'check-circle'}" style="width: 14px; height: 14px;"></i>
                <span>${issue.status === 'open' ? 'Close Issue' : 'Reopen Issue'}</span>
              </button>
            </div>
          </div>

          <div class="issue-status-strip">
            <span class="status-badge ${issue.status}">
              <i data-lucide="${issue.status === 'open' ? 'circle-dot' : 'check-circle-2'}"></i>
              <span>${issue.status === 'open' ? 'Open' : 'Closed'}</span>
            </span>
            <span>
              <strong>${issue.author}</strong> opened this issue on ${new Date(issue.createdAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} &middot; ${issue.comments.length} comment${issue.comments.length === 1 ? '' : 's'}
            </span>
          </div>
        </div>

        <!-- Comments list -->
        <div class="comments-feed">
          ${commentsHtml}
        </div>

        <!-- Composer block -->
        <div class="add-comment-wrapper">
          <div class="comment-composer">
            <div class="comment-avatar-col">
              <img src="${state.user.avatarUrl}" alt="${state.user.name}" class="avatar" />
            </div>

            <div class="composer-bubble">
              <div class="composer-tabs">
                <span>Write Comment</span>
