  const activeIssues = currentTab === "open" ? openIssues : closedIssues;

  const listHtml = activeIssues.map(issue => {
    const formattedDate = new Date(issue.createdAt).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric'
    });

    // Label tag
    let labelTag = '';
    if (issue.title.toLowerCase().includes('bug')) {
      labelTag = `<span class="label-badge label-bug">Bug</span>`;
    } else if (issue.title.toLowerCase().includes('test') || issue.title.toLowerCase().includes('doc')) {
      labelTag = `<span class="label-badge label-documentation">Documentation</span>`;
    } else {
      labelTag = `<span class="label-badge label-feature">Feature</span>`;
