      <div class="panel-container">
        <!-- Sub header (tabs: Open count, Closed count) -->
        <div class="panel-header">
          <div style="display: flex; gap: 1rem;">
            <span class="repo-tab ${currentTab === 'open' ? 'active' : ''}" id="issues-tab-open" style="padding: 0.25rem 0; border: none; cursor: pointer; display: flex; align-items: center; gap: 0.25rem;">
              <i data-lucide="circle-dot" style="width: 14px; height: 14px; color: ${currentTab === 'open' ? 'var(--accent-green)' : 'var(--text-secondary)'};"></i>
              <strong style="${currentTab === 'open' ? 'color: var(--text-primary)' : 'color: var(--text-secondary)'}">${openIssues.length} Open</strong>
            </span>

            <span class="repo-tab ${currentTab === 'closed' ? 'active' : ''}" id="issues-tab-closed" style="padding: 0.25rem 0; border: none; cursor: pointer; display: flex; align-items: center; gap: 0.25rem;">
              <i data-lucide="check" style="width: 14px; height: 14px; color: ${currentTab === 'closed' ? 'var(--accent-purple)' : 'var(--text-secondary)'};"></i>
              <strong style="${currentTab === 'closed' ? 'color: var(--text-primary)' : 'color: var(--text-secondary)'}">${closedIssues.length} Closed</strong>
            </span>
          </div>
        </div>

        <!-- List Body -->
        <div class="issue-list">
          ${listHtml || `
            <div class="empty-view-placeholder">
              <i data-lucide="circle-check-big"></i>
              <h3>No ${currentTab} issues</h3>
              <p>Everything is clear! Open a ticket if you find errors.</p>
            </div>
          `}
        </div>
      </div>
    </div>
  `;
}

export function attachIssueTrackerListeners(state, actions) {
  const repo = state.repos.find(r => r.id === state.activeRepoId);
  if (!repo) return;

  // 1. Thread detail listeners
  if (state.selectedIssueId) {
    const backBtn = document.getElementById("issue-back-btn");
    if (backBtn) {
      backBtn.addEventListener("click", () => {
        actions.selectIssue(null);
      });
    }

    const stateBtn = document.getElementById("toggle-issue-state-btn");
    if (stateBtn) {
      stateBtn.addEventListener("click", () => {
        actions.toggleIssueState(repo.id, state.selectedIssueId);
      });
    }

    const commentBtn = document.getElementById("submit-comment-btn");
    if (commentBtn) {
      commentBtn.addEventListener("click", () => {
        const textarea = document.getElementById("new-comment-body");
        if (textarea && textarea.value.trim()) {
          actions.addCommentToIssue(repo.id, state.selectedIssueId, textarea.value);
        }
      });
    }
    return;
  }

  // 2. Main List listeners
  const openTab = document.getElementById("issues-tab-open");
  if (openTab) {
    openTab.addEventListener("click", () => {
      actions.setIssuesFilterTab("open");
    });
  }

  const closedTab = document.getElementById("issues-tab-closed");
  if (closedTab) {
    closedTab.addEventListener("click", () => {
      actions.setIssuesFilterTab("closed");
    });
  }

  const issueRows = document.querySelectorAll(".issue-row");
  issueRows.forEach(row => {
    row.addEventListener("click", () => {
      const issueId = row.getAttribute("data-id");
      actions.selectIssue(issueId);
    });
  });

  const createBtn = document.getElementById("open-new-issue-modal-btn");
  if (createBtn) {
    createBtn.addEventListener("click", () => {
      actions.toggleCreateIssueModal(true);
    });
  }
}

