        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      });
      const isUser = c.author === state.user.username;

      return `
        <div class="comment-item">
          <div class="comment-avatar-col">
            <img src="${isUser ? state.user.avatarUrl : 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=60&auto=format&fit=crop&q=80'}" alt="${c.author}" class="avatar" />
          </div>

          <div class="comment-bubble">
            <div class="comment-header">
              <div class="comment-author-info">
                <span class="comment-author-name">${c.author}</span>
                <span style="color: var(--text-muted);">commented ${formattedDate}</span>
              </div>
            </div>

            <div class="comment-body">${c.body}</div>
          </div>
        </div>
      `;
    }).join('');

    // Merging controls block
    let mergeActionBlockHtml = '';
    if (pr.status === 'open') {
      mergeActionBlockHtml = `
        <div class="settings-card" style="border-color: rgba(56, 139, 253, 0.4); background-color: rgba(56, 139, 253, 0.02); margin-top: 1.5rem;">
          <div class="settings-card-body" style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 1rem; padding: 1.25rem;">
            <div style="display: flex; gap: 0.75rem; align-items: flex-start;">
              <div style="background-color: var(--accent-green-bg); color: var(--accent-green); padding: 0.5rem; border-radius: 50%; display: flex;">
                <i data-lucide="git-merge" style="width: 20px; height: 20px;"></i>
              </div>
              <div>
                <h4 style="font-size: 0.9rem; font-weight: 700;">This pull request is ready to merge</h4>
                <p style="font-size: 0.75rem; color: var(--text-secondary);">No conflicts detected. Merging will commit the changes into the main branch.</p>
              </div>
            </div>

            <button class="btn btn-primary" id="merge-pr-action-btn" style="background-color: var(--accent-green);">
              <i data-lucide="git-merge"></i>
              <span>Merge Pull Request</span>
            </button>
          </div>
        </div>
      `;
    } else if (pr.status === 'merged') {
      mergeActionBlockHtml = `
        <div class="settings-card" style="border-color: rgba(188, 140, 255, 0.4); background-color: rgba(188, 140, 255, 0.02); margin-top: 1.5rem;">
          <div class="settings-card-body" style="display: flex; align-items: center; gap: 0.75rem; padding: 1.25rem;">
            <div style="background-color: var(--accent-purple-bg); color: var(--accent-purple); padding: 0.5rem; border-radius: 50%; display: flex;">
              <i data-lucide="git-check" style="width: 20px; height: 20px;"></i>
            </div>
            <div>
              <h4 style="font-size: 0.9rem; font-weight: 700; color: var(--accent-purple);">Pull request successfully merged</h4>
              <p style="font-size: 0.75rem; color: var(--text-secondary);">Changes have been merged into main. The branch can be safely deleted.</p>
            </div>
          </div>
        </div>
      `;
    }

    return `
      <div class="issue-detail-container">
        <!-- Back navigation -->
        <button class="btn btn-sm" id="pr-back-btn">
          <i data-lucide="arrow-left" style="width: 14px; height: 14px;"></i>
          <span>Back to Pull Requests</span>
        </button>

        <!-- Header details -->
        <div class="issue-detail-title-block">
          <div class="issue-detail-title-row">
            <h2 class="issue-detail-title-text">
              <span>${pr.title}</span>
              <span class="issue-detail-number">#${pr.id}</span>
            </h2>
          </div>

          <div class="issue-status-strip">
            <span class="status-badge ${pr.status}" style="background-color: ${pr.status === 'merged' ? 'var(--accent-purple)' : 'var(--accent-green)'}">
              <i data-lucide="git-pull-request"></i>
              <span>${pr.status === 'open' ? 'Open' : 'Merged'}</span>
            </span>
            <span>
              <strong>${pr.author}</strong> wants to merge commits into <span class="commit-hash" style="font-size: 0.75rem; padding: 0.15rem 0.35rem;">main</span> from <span class="commit-hash" style="font-size: 0.75rem; padding: 0.15rem 0.35rem; color: var(--accent-orange);">patch-${pr.id}</span>
            </span>
          </div>
        </div>

        <!-- Discussion feed -->
        <div class="comments-feed">
          ${commentsHtml}
        </div>

        <!-- Action state panel -->
        ${mergeActionBlockHtml}
      </div>
    `;
  }

  // 2. PR List view
  const openPrs = repo.pullRequests.filter(p => p.status === "open");
  const mergedPrs = repo.pullRequests.filter(p => p.status === "merged" || p.status === "closed");

  const currentTab = state.prsFilterTab || "open";
  const activePrs = currentTab === "open" ? openPrs : mergedPrs;

  const listHtml = activePrs.map(pr => {
    const formattedDate = new Date(pr.createdAt).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric'
    });

    return `
      <div class="issue-row pr-row" data-id="${pr.id}">
        <div class="issue-icon ${pr.status}" style="color: ${pr.status === 'merged' ? 'var(--accent-purple)' : 'var(--accent-green)'}">
          <i data-lucide="git-pull-request" style="width: 16px; height: 16px;"></i>
        </div>

        <div class="issue-main">
          <div class="issue-title-line">
            <span class="issue-title">${pr.title}</span>
          </div>
          <div class="issue-subinfo">
            #${pr.id} opened on ${formattedDate} by ${pr.author} &middot; main &larr; patch-${pr.id}
          </div>
        </div>
      </div>
    `;
  }).join('');

  return `
    <div class="repo-tab-content">
      <div style="font-weight: 700; font-size: 0.95rem; display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;">
        <i data-lucide="git-pull-request"></i>
        <span>Pull Requests</span>
      </div>

      <!-- List container card -->
      <div class="panel-container">
        <!-- Sub header (tabs: Open count, Merged count) -->
        <div class="panel-header">
          <div style="display: flex; gap: 1rem;">
            <span class="repo-tab ${currentTab === 'open' ? 'active' : ''}" id="prs-tab-open" style="padding: 0.25rem 0; border: none; cursor: pointer; display: flex; align-items: center; gap: 0.25rem;">
              <i data-lucide="git-pull-request" style="width: 14px; height: 14px; color: ${currentTab === 'open' ? 'var(--accent-green)' : 'var(--text-secondary)'};"></i>
              <strong style="${currentTab === 'open' ? 'color: var(--text-primary)' : 'color: var(--text-secondary)'}">${openPrs.length} Open</strong>
            </span>

            <span class="repo-tab ${currentTab === 'merged' ? 'active' : ''}" id="prs-tab-merged" style="padding: 0.25rem 0; border: none; cursor: pointer; display: flex; align-items: center; gap: 0.25rem;">
              <i data-lucide="git-check-pure" class="d-none"></i>
              <i data-lucide="git-merge" style="width: 14px; height: 14px; color: ${currentTab === 'merged' ? 'var(--accent-purple)' : 'var(--text-secondary)'};"></i>
              <strong style="${currentTab === 'merged' ? 'color: var(--text-primary)' : 'color: var(--text-secondary)'}">${mergedPrs.length} Merged</strong>
            </span>
          </div>
        </div>

        <!-- List Body -->
        <div class="issue-list">
          ${listHtml || `
            <div class="empty-view-placeholder">
              <i data-lucide="git-pull-request"></i>
              <h3>No ${currentTab} pull requests</h3>
              <p>Branches look clean and sync'd with main.</p>
            </div>
          `}
        </div>
      </div>
    </div>
  `;
}

export function attachPullRequestTrackerListeners(state, actions) {
  const repo = state.repos.find(r => r.id === state.activeRepoId);
  if (!repo) return;

  // 1. PR Details view listeners
  if (state.selectedPrId) {
    const backBtn = document.getElementById("pr-back-btn");
    if (backBtn) {
      backBtn.addEventListener("click", () => {
        actions.selectPr(null);
      });
    }

    const mergeBtn = document.getElementById("merge-pr-action-btn");
    if (mergeBtn) {
      mergeBtn.addEventListener("click", () => {
        actions.mergePullRequest(repo.id, state.selectedPrId);
      });
    }
    return;
  }

  // 2. Main List listeners
  const openTab = document.getElementById("prs-tab-open");
  if (openTab) {
    openTab.addEventListener("click", () => {
      actions.setPrsFilterTab("open");
    });
  }

  const mergedTab = document.getElementById("prs-tab-merged");
  if (mergedTab) {
    mergedTab.addEventListener("click", () => {
      actions.setPrsFilterTab("merged");
    });
  }

  const prRows = document.querySelectorAll(".pr-row");
  prRows.forEach(row => {
    row.addEventListener("click", () => {
      const prId = row.getAttribute("data-id");
      actions.selectPr(prId);
    });
  });
}

