  if (!repo) return '';

  return `
    <div class="repo-tab-content" style="max-width: 800px; width: 100%;">
      <div style="font-weight: 700; font-size: 0.95rem; display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem;">
