              <span class="danger-zone-title">Change repository visibility</span>
              <span class="danger-zone-desc">This repository is currently ${repo.isPrivate ? 'private' : 'public'}.</span>
            </div>
            <button class="btn" id="settings-toggle-visibility-btn">
              Change to ${repo.isPrivate ? 'Public' : 'Private'}
            </button>
          </div>

          <div class="danger-zone-item">
            <div class="danger-zone-text">
              <span class="danger-zone-title">Delete this repository</span>
              <span class="danger-zone-desc">Once you delete a repository, there is no going back. Please be certain.</span>
            </div>
            <button class="btn btn-danger" id="settings-delete-btn">
              Delete this repository
            </button>
          </div>
        </div>
      </div>
    </div>
  `;
}

export function attachRepoSettingsListeners(state, actions) {
  const repo = state.repos.find(r => r.id === state.activeRepoId);
  if (!repo) return;

  // Rename action
  const renameBtn = document.getElementById("settings-rename-btn");
  if (renameBtn) {
    renameBtn.addEventListener("click", () => {
      const input = document.getElementById("settings-rename-input");
      if (input && input.value.trim() && input.value.trim() !== repo.name) {
        actions.renameRepository(repo.id, input.value.trim());
      }
    });
  }

  // Toggle Visibility action
  const visibilityBtn = document.getElementById("settings-toggle-visibility-btn");
  if (visibilityBtn) {
    visibilityBtn.addEventListener("click", () => {
      actions.toggleRepositoryVisibility(repo.id);
    });
  }

  // Delete action
  const deleteBtn = document.getElementById("settings-delete-btn");
  if (deleteBtn) {
    deleteBtn.addEventListener("click", () => {
      const confirmation = confirm(`Are you absolutely sure you want to delete '${repo.name}'? All files, issues, and commits will be permanently removed.`);
      if (confirmation) {
        actions.deleteRepository(repo.id);
      }
    });
  }
}

