import { initialUserData, initialRepositories } from './data/mockData.js';
import { renderNavigation, attachNavigationListeners } from './components/Navigation.js';
import { renderSidebar, attachSidebarListeners } from './components/Sidebar.js';
import { renderContributionGraph, attachContributionGraphListeners } from './components/ContributionGraph.js';
import { renderRepoList, attachRepoListListeners } from './components/RepoList.js';
import { renderRepoHeader, attachRepoHeaderListeners } from './components/RepoHeader.js';
import { renderFileExplorer, attachFileExplorerListeners } from './components/FileExplorer.js';
import { renderCommitList, attachCommitListListeners } from './components/CommitList.js';
import { renderIssueTracker, attachIssueTrackerListeners } from './components/IssueTracker.js';
import { renderPullRequestTracker, attachPullRequestTrackerListeners } from './components/PullRequestTracker.js';
import { renderRepoSettings, attachRepoSettingsListeners } from './components/RepoSettings.js';

// KEY FOR LOCALSTORAGE
const STORAGE_KEY = 'github_clone_state_v1';

class AppState {
  constructor() {
    this.state = this.loadState();
    this.actions = this.bindActions();
  }

  loadState() {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        return JSON.parse(stored);
      }
    } catch (e) {
      console.warn("Could not read from local storage, loading initial templates instead.", e);
    }

    // Default fallback state
    return {
      user: initialUserData,
      repos: initialRepositories,
      activeRepoId: null, // null means dashboard
      activeRepoTab: 'code', // code, commits, issues, pulls, settings
      activeFilePath: null,
      expandedFolders: [], // paths of expanded folders in code tree
      isEditingFile: null, // path of file being edited
      searchQuery: '',
      filterLanguage: 'All',
      filterType: 'All',
      selectedIssueId: null,
      selectedPrId: null,
      issuesFilterTab: 'open', // open, closed
      prsFilterTab: 'open', // open, merged
      isCreateRepoModalOpen: false,
      isCreateIssueModalOpen: false
    };
  }

  saveState() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(this.state));
    } catch (e) {
      console.error("Failed to write to local storage", e);
    }
  }

  setState(updates) {
    this.state = { ...this.state, ...updates };
    this.saveState();
    this.render();
  }

  bindActions() {
    return {
      navigateToDashboard: () => {
        this.setState({
          activeRepoId: null,
          selectedIssueId: null,
          selectedPrId: null,
          activeFilePath: null,
          isEditingFile: null,
          activeRepoTab: 'code'
        });
      },

      navigateToRepo: (repoId) => {
        const repo = this.state.repos.find(r => r.id === repoId);
        const defaultFile = repo && repo.files[0] ? repo.files[0].path : null;
        this.setState({
          activeRepoId: repoId,
          activeRepoTab: 'code',
          activeFilePath: defaultFile,
          selectedIssueId: null,
          selectedPrId: null,
          isEditingFile: null,
          expandedFolders: []
        });
      },

      switchTab: (tabId) => {
        this.setState({
          activeRepoTab: tabId,
          selectedIssueId: null,
          selectedPrId: null,
          isEditingFile: null
        });
      },

      selectFile: (filePath) => {
        this.setState({
          activeFilePath: filePath,
          isEditingFile: null
        });
      },

      toggleFolder: (folderPath) => {
        let expanded = [...this.state.expandedFolders];
        if (expanded.includes(folderPath)) {
          expanded = expanded.filter(p => p !== folderPath);
        } else {
          expanded.push(folderPath);
        }
        this.setState({ expandedFolders: expanded });
      },

      setEditingFile: (filePath) => {
        this.setState({ isEditingFile: filePath });
      },

      setSearchQuery: (q) => {
        this.setState({ searchQuery: q });
      },

      setFilterLanguage: (lang) => {
        this.setState({ filterLanguage: lang });
      },

      setFilterType: (type) => {
        this.setState({ filterType: type });
      },

      starRepository: (repoId) => {
        const repos = this.state.repos.map(r => {
          if (r.id === repoId) {
            return { ...r, stars: r.stars + 1 };
          }
          return r;
        });

        // Add to contributions counts too!
        const todayStr = new Date().toISOString().split('T')[0];
        const contribs = { ...this.state.user.contributions };
        const day = contribs[todayStr] || { count: 0, level: 0 };
        const newCount = day.count + 1;
        const newLevel = Math.min(4, Math.ceil(newCount / 3));
        contribs[todayStr] = { count: newCount, level: newLevel };

        this.setState({ 
          repos, 
          user: { 
            ...this.state.user, 
            starsCount: this.state.user.starsCount + 1,
            contributions: contribs 
          } 
        });
      },

      forkRepository: (repoId) => {
        const repos = this.state.repos.map(r => {
          if (r.id === repoId) {
            return { ...r, forks: r.forks + 1 };
          }
          return r;
        });

        // Add fork to user's list!
        const repoToFork = this.state.repos.find(r => r.id === repoId);
        if (repoToFork) {
          const newForkName = `${repoToFork.name}-fork`;
          if (!this.state.repos.some(r => r.name === newForkName)) {
            const newFork = {
              ...repoToFork,
              id: newForkName,
              name: newForkName,
              description: `Forked from ${this.state.user.username}/${repoToFork.name}. ${repoToFork.description}`,
              stars: 0,
              forks: 0,
              updatedAt: new Date().toISOString(),
              isPrivate: false
            };
            repos.push(newFork);
          }
        }

        this.setState({ repos });
      },

      toggleCreateRepoModal: (isOpen) => {
        this.setState({ isCreateRepoModalOpen: isOpen });
      },

      createRepository: (repoData) => {
        const repoId = repoData.name.toLowerCase().replace(/\s+/g, '-');

        // Default boiler README content
        const readmeContent = `# ${repoData.name}\n\n${repoData.description || 'Welcome to your new repository.'}`;
        const files = [
          { path: 'README.md', content: readmeContent }
        ];

        // If specific boiler language, pre-populate basic files
        if (repoData.language === 'JavaScript') {
          files.push({ path: 'index.js', content: '// Entry point\nconsole.log("Hello World!");' });
        } else if (repoData.language === 'Python') {
          files.push({ path: 'main.py', content: '# Entry point\nprint("Hello World!")' });
        }

        const newRepo = {
          id: repoId,
          name: repoData.name,
          description: repoData.description || 'No description provided.',
          isPrivate: repoData.isPrivate,
          stars: 0,
          forks: 0,
          language: repoData.language,
          updatedAt: new Date().toISOString(),
          files: files,
          commits: [
            {
              hash: Math.random().toString(16).slice(2, 9),
              message: "Initial commit",
              author: this.state.user.name,
              authorUsername: this.state.user.username,
              date: new Date().toISOString()
            }
          ],
          issues: [],
          pullRequests: []
        };

        const todayStr = new Date().toISOString().split('T')[0];
        const contribs = { ...this.state.user.contributions };
        const day = contribs[todayStr] || { count: 0, level: 0 };
        const newCount = day.count + 2; // Extra points for new repos
        const newLevel = Math.min(4, Math.ceil(newCount / 3));
        contribs[todayStr] = { count: newCount, level: newLevel };

        this.setState({
          repos: [...this.state.repos, newRepo],
          isCreateRepoModalOpen: false,
          user: { ...this.state.user, contributions: contribs }
        });

        // Auto navigate to the newly created repo
        this.actions.navigateToRepo(repoId);
      },

      selectIssue: (issueId) => {
        this.setState({ selectedIssueId: issueId });
      },

      setIssuesFilterTab: (tabName) => {
        this.setState({ issuesFilterTab: tabName });
      },

      toggleIssueState: (repoId, issueId) => {
        const repos = this.state.repos.map(r => {
          if (r.id === repoId) {
            const issues = r.issues.map(i => {
              if (i.id === Number(issueId)) {
                const newStatus = i.status === 'open' ? 'closed' : 'open';
                return { ...i, status: newStatus };
              }
              return i;
            });
            return { ...r, issues };
          }
          return r;
        });
        this.setState({ repos });
      },

      toggleCreateIssueModal: (isOpen) => {
        this.setState({ isCreateIssueModalOpen: isOpen });
      },

      createIssue: (repoId, issueData) => {
        const repos = this.state.repos.map(r => {
          if (r.id === repoId) {
            const nextId = r.issues.length ? Math.max(...r.issues.map(i => i.id)) + 1 : 1;
            const newIssue = {
              id: nextId,
              title: issueData.title,
              description: issueData.description || 'No description provided.',
              status: 'open',
              author: this.state.user.username,
              createdAt: new Date().toISOString(),
              comments: []
            };
            return { ...r, issues: [newIssue, ...r.issues] };
          }
          return r;
        });

        this.setState({
          repos,
          isCreateIssueModalOpen: false
        });
      },

      addCommentToIssue: (repoId, issueId, commentText) => {
        const repos = this.state.repos.map(r => {
          if (r.id === repoId) {
            const issues = r.issues.map(i => {
              if (i.id === Number(issueId)) {
                const newComment = {
                  author: this.state.user.username,
                  isOwner: true,
                  createdAt: new Date().toISOString(),
                  body: commentText
                };
                return { ...i, comments: [...i.comments, newComment] };
              }
              return i;
            });
            return { ...r, issues };
          }
          return r;
        });
        this.setState({ repos });
      },

      selectPr: (prId) => {
        this.setState({ selectedPrId: prId });
      },

      setPrsFilterTab: (tabName) => {
        this.setState({ prsFilterTab: tabName });
      },

      mergePullRequest: (repoId, prId) => {
        const todayStr = new Date().toISOString().split('T')[0];
        const hash = Math.random().toString(16).slice(2, 9);

        const repos = this.state.repos.map(r => {
          if (r.id === repoId) {
            let prTitle = '';
            const pullRequests = r.pullRequests.map(p => {
              if (p.id === Number(prId)) {
                prTitle = p.title;
                return { ...p, status: 'merged', mergedAt: new Date().toISOString() };
              }
              return p;
            });

            // Create merge commit in timeline
            const mergeCommit = {
              hash,
              message: `Merge pull request #${prId} from patch-${prId}\n\n${prTitle}`,
              author: this.state.user.name,
              authorUsername: this.state.user.username,
              date: new Date().toISOString()
            };

            return {
              ...r,
              pullRequests,
              commits: [mergeCommit, ...r.commits]
            };
          }
          return r;
        });

        // Add to contributions count
        const contribs = { ...this.state.user.contributions };
        const day = contribs[todayStr] || { count: 0, level: 0 };
        const newCount = day.count + 3; // Extra points for mergers
        const newLevel = Math.min(4, Math.ceil(newCount / 3));
        contribs[todayStr] = { count: newCount, level: newLevel };

        this.setState({
          repos,
          user: { ...this.state.user, contributions: contribs }
        });
      },

      renameRepository: (repoId, newName) => {
        const newId = newName.toLowerCase().replace(/\s+/g, '-');
        const repos = this.state.repos.map(r => {
          if (r.id === repoId) {
            return { ...r, id: newId, name: newName };
          }
          return r;
        });

        this.setState({
          repos,
          activeRepoId: newId // Update the active ID key
        });
      },

      toggleRepositoryVisibility: (repoId) => {
        const repos = this.state.repos.map(r => {
          if (r.id === repoId) {
            return { ...r, isPrivate: !r.isPrivate };
          }
          return r;
        });
        this.setState({ repos });
      },

      deleteRepository: (repoId) => {
        const repos = this.state.repos.filter(r => r.id !== repoId);
        this.setState({
          repos,
          activeRepoId: null, // Return to dashboard
          selectedIssueId: null,
          selectedPrId: null
        });
      },

      commitFileChanges: (repoId, filePath, content, commitMessage) => {
        const hash = Math.random().toString(16).slice(2, 9);
        const todayStr = new Date().toISOString().split('T')[0];

        const repos = this.state.repos.map(r => {
          if (r.id === repoId) {
            // 1. Update file content
            const files = r.files.map(f => {
              if (f.path === filePath) {
                return { ...f, content };
              }
              return f;
            });

            // 2. Add commit to log
            const newCommit = {
              hash,
              message: commitMessage,
              author: this.state.user.name,
              authorUsername: this.state.user.username,
              date: new Date().toISOString()
            };

            return {
              ...r,
              files,
              commits: [newCommit, ...r.commits],
              updatedAt: new Date().toISOString()
            };
          }
          return r;
        });

        // Add to contributions counts
        const contribs = { ...this.state.user.contributions };
        const day = contribs[todayStr] || { count: 0, level: 0 };
        const newCount = day.count + 1;
        const newLevel = Math.min(4, Math.ceil(newCount / 3));
        contribs[todayStr] = { count: newCount, level: newLevel };

        this.setState({
          repos,
          isEditingFile: null,
          user: { ...this.state.user, contributions: contribs }
        });
      }
    };
  }

  // CORE RENDER METHOD
  render() {
    const container = document.getElementById("app");
    if (!container) return;

    // Build sub components HTML
    const navHtml = renderNavigation(this.state, this.actions);
    const sidebarHtml = renderSidebar(this.state, this.actions);

    let mainPanelHtml = '';

    // Route matching
    if (this.state.activeRepoId === null) {
      // Dashboard profile + repo lists page
      const graphHtml = renderContributionGraph(this.state, this.actions);
      const listHtml = renderRepoList(this.state, this.actions);

      mainPanelHtml = `
        <div class="content-wrapper" style="display: flex; flex-direction: column;">
          ${graphHtml}
          ${listHtml}
        </div>
      `;
    } else {
      // Repository Detail Page
      const repoHeaderHtml = renderRepoHeader(this.state, this.actions);

      let tabPaneHtml = '';
      if (this.state.activeRepoTab === 'code') {
        tabPaneHtml = renderFileExplorer(this.state, this.actions);
      } else if (this.state.activeRepoTab === 'commits') {
        tabPaneHtml = renderCommitList(this.state, this.actions);
      } else if (this.state.activeRepoTab === 'issues') {
        tabPaneHtml = renderIssueTracker(this.state, this.actions);
      } else if (this.state.activeRepoTab === 'pulls') {
        tabPaneHtml = renderPullRequestTracker(this.state, this.actions);
      } else if (this.state.activeRepoTab === 'settings') {
        tabPaneHtml = renderRepoSettings(this.state, this.actions);
      }

      mainPanelHtml = `
        <div class="content-wrapper">
          ${repoHeaderHtml}
          ${tabPaneHtml}
        </div>
      `;
    }

    // Modal windows html definitions
    let modalsHtml = '';
    if (this.state.isCreateRepoModalOpen) {
      modalsHtml += `
        <div class="modal-backdrop" id="create-repo-backdrop">
          <div class="modal-content">
            <div class="modal-header">
              <h3>Create a new repository</h3>
              <button class="modal-close" id="close-repo-modal-btn">
                <i data-lucide="x"></i>
              </button>
            </div>

            <div class="modal-body">
              <div class="form-group">
                <label for="new-repo-name">Repository name <span class="text-error">*</span></label>
                <input type="text" class="form-input" id="new-repo-name" placeholder="e.g. quantum-gravity" />
              </div>

              <div class="form-group">
                <label for="new-repo-desc">Description <span style="font-weight:400; color:var(--text-secondary);">(optional)</span></label>
                <input type="text" class="form-input" id="new-repo-desc" placeholder="Brief outline of project..." />
              </div>

              <div class="form-group">
                <label>Primary Language</label>
                <select class="select-filter" id="new-repo-lang" style="width: 100%;">
                  <option value="JavaScript">JavaScript</option>
                  <option value="CSS">CSS</option>
                  <option value="HTML">HTML</option>
                  <option value="Python">Python</option>
                  <option value="TypeScript">TypeScript</option>
                </select>
              </div>

              <div class="form-group-row" style="margin-top: 0.5rem;">
                <div class="form-radio-card selected" id="radio-public-card">
                  <i data-lucide="book-marked" style="color: var(--accent-blue);"></i>
                  <div class="radio-details">
                    <span class="radio-title">Public</span>
                    <span class="radio-desc">Anyone on the internet can see this repository.</span>
                  </div>
                </div>

                <div class="form-radio-card" id="radio-private-card">
                  <i data-lucide="lock" style="color: var(--text-secondary);"></i>
                  <div class="radio-details">
                    <span class="radio-title">Private</span>
                    <span class="radio-desc">You choose who can see and commit to this repository.</span>
                  </div>
                </div>
              </div>
            </div>

            <div class="modal-footer">
              <button class="btn" id="cancel-repo-modal-btn">Cancel</button>
              <button class="btn btn-primary" id="submit-new-repo-btn">Create Repository</button>
            </div>
          </div>
        </div>
      `;
    }

    if (this.state.isCreateIssueModalOpen) {
      modalsHtml += `
        <div class="modal-backdrop" id="create-issue-backdrop">
          <div class="modal-content">
            <div class="modal-header">
              <h3>Open a new issue</h3>
              <button class="modal-close" id="close-issue-modal-btn">
                <i data-lucide="x"></i>
              </button>
            </div>

            <div class="modal-body">
              <div class="form-group">
                <label for="new-issue-title">Title <span class="text-error">*</span></label>
                <input type="text" class="form-input" id="new-issue-title" placeholder="Title text..." />
              </div>

              <div class="form-group">
                <label for="new-issue-desc">Description</label>
                <textarea class="form-input" id="new-issue-desc" placeholder="Describe the problem..." rows="4" style="resize: vertical;"></textarea>
              </div>
            </div>

            <div class="modal-footer">
              <button class="btn" id="cancel-issue-modal-btn">Cancel</button>
              <button class="btn btn-primary" id="submit-new-issue-btn">Submit new issue</button>
            </div>
          </div>
        </div>
      `;
    }

    // Combine into main app layout grid
    container.innerHTML = `
      ${navHtml}

      <main class="main-container">
        ${sidebarHtml}
        ${mainPanelHtml}
      </main>

      ${modalsHtml}
    `;

    // Trigger Lucide to render all SVGs
    if (window.lucide) {
      window.lucide.createIcons();
    }

    // Attach listeners
    attachNavigationListeners(this.state, this.actions);
    attachSidebarListeners(this.state, this.actions);

    if (this.state.activeRepoId === null) {
      attachContributionGraphListeners(this.state, this.actions);
      attachRepoListListeners(this.state, this.actions);
    } else {
      attachRepoHeaderListeners(this.state, this.actions);

      if (this.state.activeRepoTab === 'code') {
        attachFileExplorerListeners(this.state, this.actions);
      } else if (this.state.activeRepoTab === 'commits') {
        attachCommitListListeners(this.state, this.actions);
      } else if (this.state.activeRepoTab === 'issues') {
        attachIssueTrackerListeners(this.state, this.actions);
      } else if (this.state.activeRepoTab === 'pulls') {
        attachPullRequestTrackerListeners(this.state, this.actions);
      } else if (this.state.activeRepoTab === 'settings') {
        attachRepoSettingsListeners(this.state, this.actions);
      }
    }

    // Attach Local Modal Listeners
    this.attachModalListeners();
  }

  attachModalListeners() {
    // 1. New repo modal listeners
    if (this.state.isCreateRepoModalOpen) {
      const closeBtn = document.getElementById("close-repo-modal-btn");
      const cancelBtn = document.getElementById("cancel-repo-modal-btn");
      const submitBtn = document.getElementById("submit-new-repo-btn");
      const publicRadio = document.getElementById("radio-public-card");
      const privateRadio = document.getElementById("radio-private-card");

      let isPrivate = false;

      const toggleRadio = (makePrivate) => {
        isPrivate = makePrivate;
        if (isPrivate) {
          privateRadio.classList.add("selected");
          publicRadio.classList.remove("selected");
          // Update icon coloring
          privateRadio.querySelector("i").style.color = "var(--accent-blue)";
          publicRadio.querySelector("i").style.color = "var(--text-secondary)";
        } else {
          publicRadio.classList.add("selected");
          privateRadio.classList.remove("selected");
          publicRadio.querySelector("i").style.color = "var(--accent-blue)";
          privateRadio.querySelector("i").style.color = "var(--text-secondary)";
        }
      };

      if (publicRadio) publicRadio.addEventListener("click", () => toggleRadio(false));
      if (privateRadio) privateRadio.addEventListener("click", () => toggleRadio(true));

      const closeModal = () => this.actions.toggleCreateRepoModal(false);
      if (closeBtn) closeBtn.addEventListener("click", closeModal);
      if (cancelBtn) cancelBtn.addEventListener("click", closeModal);

      if (submitBtn) {
        submitBtn.addEventListener("click", () => {
          const nameInput = document.getElementById("new-repo-name");
          const descInput = document.getElementById("new-repo-desc");
          const langSelect = document.getElementById("new-repo-lang");

          const name = nameInput ? nameInput.value.trim() : '';
          const description = descInput ? descInput.value.trim() : '';
          const language = langSelect ? langSelect.value : 'JavaScript';

          if (!name) {
            alert("Repository name is required!");
            return;
          }

          this.actions.createRepository({ name, description, isPrivate, language });
        });
      }
    }

    // 2. New issue modal listeners
    if (this.state.isCreateIssueModalOpen) {
      const closeBtn = document.getElementById("close-issue-modal-btn");
      const cancelBtn = document.getElementById("cancel-issue-modal-btn");
      const submitBtn = document.getElementById("submit-new-issue-btn");

      const closeModal = () => this.actions.toggleCreateIssueModal(false);
      if (closeBtn) closeBtn.addEventListener("click", closeModal);
      if (cancelBtn) cancelBtn.addEventListener("click", closeModal);

      if (submitBtn) {
        submitBtn.addEventListener("click", () => {
          const titleInput = document.getElementById("new-issue-title");
          const descInput = document.getElementById("new-issue-desc");

          const title = titleInput ? titleInput.value.trim() : '';
          const description = descInput ? descInput.value.trim() : '';

          if (!title) {
            alert("Issue title is required!");
            return;
          }

          this.actions.createIssue(this.state.activeRepoId, { title, description });
        });
      }
    }
  }
}

// INITIALIZE APP
document.addEventListener("DOMContentLoaded", () => {
  const app = new AppState();
  app.render();
});

